files.hooks/register.ts:
// lk-secret-guard: a seatbelt that stops credential-shaped strings and a private
// deny-list of words from being written into files or shell commands.
//
// tool.call (Write, Edit, MultiEdit, NotebookEdit, Bash): scans only the NEW
// text the call would write. A "block" finding refuses the call; a "warn"
// finding asks the user (Allow once / Block). Subagents' calls are guarded too.
// Every decision is logged in $.state with the value masked, never raw.
//
// Helpers that take `$` are top-level functions in this file, as the static
// analysis requires; the pattern table and pure matching live in ./patterns.

import { atom, read, update } from 'claude-code'
import type { EngineInterface, On } from 'claude-code'

import type { GuardConfig, LogRow } from '../types'
import {
  askQuestion,
  bandParts,
  blockMessage,
  judge,
  mergeConfig,
  parseConfig,
  scan,
  targetOf,
  type Config,
  type Finding,
} from './patterns'
import { TONES, makeKit } from './kit'
import type { Elements } from './kit'
import { activeRules, lastBlocked, outcomeOf, ruleRows, wordScope } from './pane'

const PANE_ID = 'secret-guard'
const LOG_KEEP = 200
const PANE_ROWS = 20
/** Secondary text: the theme's quiet key. */
const QUIET = TONES.muted.fg

const enabledAtom = atom({ plugin: 'lk-secret-guard', key: 'enabled' } as const, true)
const bandAtom = atom({ plugin: 'lk-secret-guard', key: 'band' } as const, true)
const logAtom = atom({ plugin: 'lk-secret-guard', key: 'log' } as const, [] as LogRow[])
const blockedAtom = atom({ plugin: 'lk-secret-guard', key: 'blocked' } as const, 0)
const allowedAtom = atom({ plugin: 'lk-secret-guard', key: 'allowed' } as const, 0)
const configAtom = atom({ plugin: 'lk-secret-guard', key: 'config' } as const, null as GuardConfig | null)
const filesAtom = atom({ plugin: 'lk-secret-guard', key: 'configFiles' } as const, [] as string[])
const errorsAtom = atom({ plugin: 'lk-secret-guard', key: 'configErrors' } as const, [] as string[])

const USAGE =
  'usage: /secret-guard (open the pane) · on · off · reload · test <text> · band on|off'

export function register(on: On) {
  on('session.start', async ($, e, next) => {
    try {
      await loadConfig($)
    } catch {
      // The guard loads the config again on the first guarded call.
    }
    try {
      await loadBand($)
    } catch {
      // The band stays at its default.
    }
    try {
      await $.command.register({
        name: 'secret-guard',
        description: 'Secret guard: status pane, on/off, reload config, test a string, band on/off',
        argumentHint: '[on|off|reload|test <text>|band on|off]',
        immediate: true,
      })
    } catch {
      // The name is taken; the guard itself still runs.
    }
    return next(e)
  })

  // /clear, /resume and /branch reset $.state, and session.start does not fire again.
  on('classic.SessionStart', { source: ['clear', 'resume', 'fork'] }, async ($, e, next) => {
    try {
      await loadConfig($)
      await loadBand($)
    } catch {
      // Loaded again lazily on the next guarded call.
    }
    return next(e)
  })

  on('tool.call', { tool: ['Write', 'Edit', 'MultiEdit', 'NotebookEdit', 'Bash'] }, async ($, e, next) => {
    const fields = e as unknown as Record<string, unknown>
    const target = targetOf(fields)
    if (target === null || target.texts.length === 0) return next(e)
    if (!(await read($, enabledAtom))) return next(e)

    const config = await ensureConfig($)
    const ctx = await pathCtx($)
    const verdict = judge(target, config, ctx)
    if (verdict.findings.length === 0) return next(e)

    const agentId = typeof fields.agentId === 'string' && fields.agentId !== '' ? fields.agentId : undefined
    const first = verdict.findings[0]
    if (first.action === 'block') {
      await record($, first, target.where, 'blocked', agentId)
      return { deny: blockMessage(first, target.where) }
    }

    const warns = verdict.findings
    let answer: string | null = null
    try {
      answer = await $.ui.ask(askQuestion(first, target.where, warns.length - 1), ['Allow once', 'Block'])
    } catch {
      answer = null
    }
    if (answer === null) {
      // Dismissed, or nobody to ask. Non-interactive runs (-p, SDK) allow with a toast;
      // a person who dismissed the question gets the safe answer.
      const surfaces = await $.session.surfaces()
      if (surfaces.length === 0) {
        $.ui.toast(`possible ${first.kind} in ${target.where} (${first.masked}) allowed: no one to ask`)
        await record($, first, target.where, 'allowed', agentId)
        return next(e)
      }
      await record($, first, target.where, 'blocked', agentId)
      return { deny: blockMessage(first, target.where) + ' (The question was dismissed.)' }
    }
    if (answer === 'Allow once') {
      await record($, first, target.where, 'warned-allowed', agentId)
      return next(e)
    }
    await record($, first, target.where, 'blocked', agentId)
    return { deny: blockMessage(first, target.where) + ' The user chose Block.' }
  }).catch(async ($, e, next) => {
    const kind = next.error?.kind ?? 'throw'
    const message = String(next.error?.message ?? '').replace(/\s+/g, ' ').slice(0, 120)
    return {
      deny: `secret-guard failed (${kind}: ${message}), so this call was not run. Retry, or run /secret-guard off if the guard is broken.`,
    }
  })

  on('command.run', { command: 'secret-guard' }, async ($, e) => {
    const args = typeof e.args === 'string' ? e.args.trim() : ''
    const [sub = '', ...rest] = args.split(/\s+/)
    const verb = sub.toLowerCase()

    if (verb === '') {
      await $.ui.open({ id: PANE_ID, title: 'Secret guard', focus: true, closeOnEscape: true })
      return {}
    }
    if (verb === 'off') {
      await update($, enabledAtom, () => false)
      return { text: 'off for this session. Writes and commands are not checked. Run /secret-guard on to resume.' }
    }
    if (verb === 'on') {
      await update($, enabledAtom, () => true)
      return { text: 'on. Writes and commands are checked for credentials and deny-listed words.' }
    }
    if (verb === 'reload') {
      const config = await loadConfig($)
      const files = await read($, filesAtom)
      const errors = await read($, errorsAtom)
      return { text: describeConfig(config, files, errors) }
    }
    if (verb === 'band') {
      const value = (rest[0] ?? '').toLowerCase()
      if (value !== 'on' && value !== 'off') return { text: 'usage: /secret-guard band on|off' }
      await $.store.set('band', value === 'on')
      await update($, bandAtom, () => value === 'on')
      return { text: `band ${value} (saved for future sessions).` }
    }
    if (verb === 'test') {
      const text = args.replace(/^test\s*/i, '')
      if (text === '') return { text: 'usage: /secret-guard test <text>' }
      const config = await ensureConfig($)
      return { text: describeTest(scan(text, { config, wordsApply: true }), await read($, enabledAtom)) }
    }
    return { text: USAGE }
  })

  // The band, one kit line: a bold label, then the blocked and allowed counts as chips (danger and ok
  // once nonzero, else quiet); when the guard is off, an `off for this session` chip in danger and how
  // to resume on the right side, in the default text color (kit.line draws its right side quiet).
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const isOn = await read($, enabledAtom)
    const showBand = await read($, bandAtom)
    const blocked = await read($, blockedAtom)
    const allowed = await read($, allowedAtom)
    if (isOn && (!showBand || blocked + allowed === 0)) return next(e)
    const parts = bandParts(isOn, blocked, allowed)
    const ui = $.ui.resolve(e)
    const { Box } = ui
    const kit = makeKit(ui as unknown as Elements, e.surface)
    const drawn = (
      parts.urgent && parts.right
        ? Box({
            flexDirection: 'row',
            justifyContent: 'space-between',
            columnGap: 2,
            children: [kit.line('secret-guard', parts.chips) as ReturnType<typeof Box>, kit.text(parts.right, { wrap: 'truncate' }) as ReturnType<typeof Box>],
          })
        : kit.line('secret-guard', parts.chips, parts.right)
    ) as ReturnType<typeof Box>
    const line = Box({ key: 'secret-guard-band', flexDirection: 'column', children: [drawn] })
    const theirs = await next(e)
    if (theirs === null || theirs === undefined) return line
    return Box({ flexDirection: 'column', children: [line, theirs] })
  })

  // The pane, drawn with the kit: the last block as the hero, tiles, then the recent decisions,
  // the rules and the config files as sections. Values are masked; word lists are only counted.
  // A page: one row between blocks; the rows inside a section stay together.
  on('ui.render', { component: 'Pane' }, async ($, e, next) => {
    if (e.requestId !== PANE_ID) return next(e)
    const kit = makeKit($.ui.resolve(e) as unknown as Elements, e.surface)
    const isOn = await read($, enabledAtom)
    const showBand = await read($, bandAtom)
    const blocked = await read($, blockedAtom)
    const allowed = await read($, allowedAtom)
    const config = await read($, configAtom)
    const files = await read($, filesAtom)
    const errors = await read($, errorsAtom)
    const log = await read($, logAtom)
    const rows = log.slice(-PANE_ROWS).reverse()
    const last = lastBlocked(log)
    const dim = (s: string) => kit.text(s, { color: QUIET, wrap: 'truncate' })

    const hero = last
      ? kit.hero({
          kicker: 'secret guard',
          title: `Blocked ${last.kind} in ${last.where}`,
          sub: [clock(last.at), last.masked, last.agentId ? 'agent ' + last.agentId : ''].filter(Boolean).join(' · '),
          tone: 'danger',
        })
      : kit.hero({
          kicker: 'secret guard',
          title: 'Nothing blocked yet',
          sub: isOn
            ? 'Checking the new text of Write, Edit, MultiEdit, NotebookEdit and Bash calls'
            : 'The guard is off for this session · /secret-guard on to resume',
          tone: isOn ? 'ok' : 'danger',
        })

    const status = kit.row({
      key: 'status',
      left: [
        kit.text(isOn ? 'Status: ON' : 'Status: OFF for this session', {
          color: TONES[isOn ? 'ok' : 'danger'].fg,
          bold: true,
          wrap: 'truncate',
        }),
      ],
      right: `Band above the prompt: ${showBand ? 'on' : 'off'}`,
    })

    const recent = kit.stack([
      kit.section(`Recent · ${rows.length}`, rows.length > 0 ? 'newest first' : undefined),
      ...(rows.length > 0
        ? rows.map((r, i) => {
            const o = outcomeOf(r.action)
            return kit.row({
              key: `row-${i}`,
              left: [
                dim(clock(r.at)),
                kit.pill(o.label, o.tone),
                kit.text(r.kind, { bold: true, wrap: 'truncate' }),
                kit.text(`in ${r.where} (${r.masked})`, { wrap: 'truncate' }),
              ],
              right: r.agentId ? 'agent ' + r.agentId : '',
              align: 'center',
            })
          })
        : [dim('No decisions yet this session')]),
    ])

    const rulesList = config === null ? [] : ruleRows(config)
    const off = rulesList.filter(r => !r.on).length
    const rules =
      config === null
        ? kit.stack([kit.section('Rules'), dim('Not loaded yet: /secret-guard reload reads the config files')])
        : kit.stack([
            kit.section(`Rules · ${activeRules(config)}`, off > 0 ? `${off} off` : undefined),
            ...rulesList.map(r =>
              kit.row({
                key: r.key,
                left: [
                  kit.text(r.name, r.on ? { wrap: 'truncate' } : { color: QUIET, wrap: 'truncate' }),
                  kit.pill(r.source, r.source === 'config' ? 'accent' : 'muted'),
                ],
                right: r.right,
                align: 'center',
              }),
            ),
          ])

    const configSection = kit.stack([
      kit.section(`Config · ${files.length}`, errors.length > 0 ? `${errors.length} ignored` : undefined),
      ...(files.length > 0
        ? files.map((f, i) => kit.row({ key: `file-${i}`, left: [kit.text(f, { wrap: 'truncate' })], right: 'loaded' }))
        : [dim('No files found (built-in patterns only)')]),
      ...errors.map((err, i) =>
        kit.row({ key: `err-${i}`, left: [kit.pill('ignored', 'danger'), kit.text(err, { color: TONES.danger.fg, wrap: 'truncate' })], align: 'center' }),
      ),
      config === null ? null : dim(`${config.allowPaths.length} allowPaths · word lists apply ${wordScope(config)}`),
    ])

    return kit.page([
      hero,
      kit.tiles([
        { label: 'Blocked', value: String(blocked), tone: blocked > 0 ? 'danger' : 'muted' },
        { label: 'Allowed', value: String(allowed), tone: allowed > 0 ? 'ok' : 'muted' },
        { label: 'Rules', value: config === null ? '—' : String(activeRules(config)), tone: 'info' },
      ]),
      status,
      recent,
      rules,
      configSection,
      kit.buttons([
        {
          key: 'close',
          label: 'Close',
          hotkey: 'c',
          plain: true,
          onPress: async () => {
            await $.ui.close({ id: PANE_ID })
          },
        },
      ]),
    ]) as never
  })
}

// ---- Helpers that take $ ----------------------------------------------------

async function pathCtx($: EngineInterface) {
  const cwd = await $.session.cwd()
  const home = (await $.env.get('HOME')) ?? ''
  return { cwd, home }
}

async function ensureConfig($: EngineInterface): Promise<Config> {
  const cached = await read($, configAtom)
  if (cached !== null) return cached
  return loadConfig($)
}

/** Reads ~/.claude/secret-guard.json, then <cwd>/.claude/secret-guard.json; later wins. */
async function loadConfig($: EngineInterface): Promise<Config> {
  const home = (await $.env.get('HOME')) ?? ''
  const cwd = (await $.session.cwd()).replace(/\/+$/, '')
  const candidates: string[] = []
  if (home !== '') candidates.push(home.replace(/\/+$/, '') + '/.claude/secret-guard.json')
  const project = cwd + '/.claude/secret-guard.json'
  if (!candidates.includes(project)) candidates.push(project)

  const layers = []
  const files: string[] = []
  const errors: string[] = []
  for (const path of candidates) {
    let exists = false
    try {
      exists = await $.fs.exists(path)
    } catch {
      exists = false
    }
    if (!exists) continue
    try {
      const text = String(await $.fs.read(path))
      layers.push(parseConfig(text))
      files.push(path)
    } catch {
      // Never echo the parser's message: it can quote the file, and the file holds private words.
      errors.push(`${path} is unreadable or not a JSON object`)
    }
  }
  const merged = mergeConfig(layers)
  await update($, configAtom, () => merged)
  await update($, filesAtom, () => files)
  await update($, errorsAtom, () => errors)
  if (errors.length > 0) {
    $.ui.toast(`config ignored: ${errors.join('; ')}`)
  }
  return merged
}

async function loadBand($: EngineInterface) {
  const saved = await $.store.get('band')
  await update($, bandAtom, () => saved !== false)
}

async function record(
  $: EngineInterface,
  f: Finding,
  where: string,
  action: LogRow['action'],
  agentId: string | undefined,
) {
  const row: LogRow = { at: Date.now(), kind: f.kind, where, masked: f.masked, action }
  if (agentId !== undefined) row.agentId = agentId
  await update($, logAtom, rows => [...rows, row].slice(-LOG_KEEP))
  if (action === 'blocked') {
    await update($, blockedAtom, n => n + 1)
  } else {
    await update($, allowedAtom, n => n + 1)
  }
}

// ---- Pure text helpers --------------------------------------------------------

function clock(at: number): string {
  try {
    return new Date(at).toISOString().slice(11, 19)
  } catch {
    return '--:--:--'
  }
}

function rulesSummary(c: Config): string {
  const scope = c.publicPaths === null ? 'everywhere' : `only in ${c.publicPaths.length} public path(s)`
  const disabled = c.disabledKinds.length > 0 ? ` · disabled: ${c.disabledKinds.join(', ')}` : ''
  return `Rules: ${c.deny.length} deny word(s), ${c.warn.length} warn word(s), applied ${scope} · ${c.allowPaths.length} allowPaths${disabled}`
}

function describeConfig(c: Config, files: string[], errors: string[]): string {
  const found = files.length > 0 ? `reloaded ${files.join(', ')}.` : 'reloaded: no config files found, built-in patterns only.'
  const bad = errors.length > 0 ? ` Ignored: ${errors.join('; ')}.` : ''
  return `${found} ${rulesSummary(c)}.${bad}`
}

function describeTest(findings: Finding[], isOn: boolean): string {
  const off = isOn ? '' : ' (The guard is off for this session, so nothing would be stopped right now.)'
  if (findings.length === 0) return `nothing in that text would be flagged.${off}`
  const lines = findings.map(f => `- would ${f.action === 'block' ? 'BLOCK' : 'ASK (warn)'}: ${f.kind} (${f.masked})`)
  return `${findings.length} finding(s); word lists applied as if the path were public:\n${lines.join('\n')}${off}`
}

files.hooks/patterns.ts:
// lk-secret-guard: the pattern table and the pure matching helpers.
//
// Nothing in this file touches the mods API, so it can be imported by the
// hooks module and unit tested directly. Every function is total: bad input
// yields "no finding", never a throw.

export type Action = 'block' | 'warn'

export type Pattern = {
  /** Stable id, used by `disabledKinds` in the config file. */
  id: string
  /** Human label shown in messages. */
  kind: string
  action: Action
  regex: RegExp
  /** Capture group holding the value to mask and placeholder-check (0 = whole match). */
  group?: number
  /** When true, values that look like placeholders are ignored. */
  skipPlaceholders?: boolean
}

/** Built-in credential patterns. Order matters only for which finding is reported first. */
export const PATTERNS: readonly Pattern[] = [
  { id: 'private-key', kind: 'private key block', action: 'block', regex: /-----BEGIN (?:RSA |EC |OPENSSH |PGP |DSA )?PRIVATE KEY-----/g },
  { id: 'aws-access-key', kind: 'AWS access key', action: 'block', regex: /AKIA[0-9A-Z]{16}/g },
  { id: 'anthropic-key', kind: 'Anthropic API key', action: 'block', regex: /sk-ant-[A-Za-z0-9_-]{20,}/g },
  { id: 'openai-key', kind: 'OpenAI API key', action: 'block', regex: /sk-proj-[A-Za-z0-9_-]{20,}/g },
  { id: 'openai-key', kind: 'OpenAI API key', action: 'block', regex: /sk-[A-Za-z0-9]{20,}/g },
  { id: 'github-token', kind: 'GitHub token', action: 'block', regex: /gh[pousr]_[A-Za-z0-9]{36,}/g },
  { id: 'github-token', kind: 'GitHub token', action: 'block', regex: /github_pat_[A-Za-z0-9_]{22,}/g },
  { id: 'slack-token', kind: 'Slack token', action: 'block', regex: /xox[baprs]-[A-Za-z0-9-]{10,}/g },
  { id: 'google-api-key', kind: 'Google API key', action: 'block', regex: /AIza[0-9A-Za-z_-]{35}/g },
  { id: 'stripe-key', kind: 'Stripe live key', action: 'block', regex: /(?:sk|rk)_live_[0-9a-zA-Z]{20,}/g },
  { id: 'twilio-key', kind: 'Twilio API key', action: 'warn', regex: /\bSK[0-9a-f]{32}\b/g },
  { id: 'jwt', kind: 'JWT', action: 'warn', regex: /eyJ[A-Za-z0-9_-]{10,}\.eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}/g },
  {
    id: 'generic-secret',
    kind: 'hard-coded secret',
    action: 'warn',
    regex: /(password|passwd|secret|api[_-]?key|token)\s*[:=]\s*['"]?([^\s'"]{8,})/gi,
    group: 2,
    skipPlaceholders: true,
  },
]

/** Every id `disabledKinds` accepts. */
export const KIND_IDS: readonly string[] = [...new Set(PATTERNS.map(p => p.id))]

const PLACEHOLDER_MARKERS = [
  'xxx', 'your_', '<', '${', 'example', 'changeme', 'placeholder', 'redacted',
  // References to the environment are not literal secrets.
  'process.env', 'os.environ', 'getenv',
]

/** True when a value is an obvious placeholder rather than a real secret. */
export function isPlaceholder(value: string): boolean {
  const v = value.toLowerCase()
  if (PLACEHOLDER_MARKERS.some(m => v.includes(m))) return true
  if (v.length > 0 && [...v].every(c => c === v[0])) return true
  return false
}

/**
 * Masks a value so the whole of it is never shown: the first 4 and last 3
 * characters with an ellipsis between. Shorter values reveal less, so that at
 * most about half of any value is ever visible.
 */
export function mask(value: string): string {
  const s = String(value ?? '')
  const n = s.length
  if (n >= 12) return s.slice(0, 4) + '…' + s.slice(-3)
  if (n >= 6) return s.slice(0, 2) + '…' + s.slice(-1)
  if (n >= 2) return s.slice(0, 1) + '…'
  return '…'
}

export type Config = {
  deny: string[]
  warn: string[]
  /** null when no config file set it: the word lists then apply everywhere. */
  publicPaths: string[] | null
  allowPaths: string[]
  disabledKinds: string[]
}

export const EMPTY_CONFIG: Config = { deny: [], warn: [], publicPaths: null, allowPaths: [], disabledKinds: [] }

function strings(v: unknown): string[] | undefined {
  if (!Array.isArray(v)) return undefined
  return v.filter((x): x is string => typeof x === 'string' && x.trim() !== '').map(x => x.trim())
}

/** Parses one config file's text. Throws on malformed JSON (the caller records it). */
export function parseConfig(text: string): Partial<Config> {
  const raw = JSON.parse(text) as unknown
  if (raw === null || typeof raw !== 'object' || Array.isArray(raw)) {
    throw new Error('the top level must be a JSON object')
  }
  const o = raw as Record<string, unknown>
  const out: Partial<Config> = {}
  const deny = strings(o.deny)
  const warn = strings(o.warn)
  const publicPaths = strings(o.publicPaths)
  const allowPaths = strings(o.allowPaths)
  const disabledKinds = strings(o.disabledKinds)
  if (deny) out.deny = deny
  if (warn) out.warn = warn
  if (publicPaths) out.publicPaths = publicPaths
  if (allowPaths) out.allowPaths = allowPaths
  if (disabledKinds) out.disabledKinds = disabledKinds
  return out
}

/**
 * Merges config layers, global first, project last. A later file replaces
 * `publicPaths`, `allowPaths` and `disabledKinds` when it sets them. The
 * `deny` and `warn` word lists are unioned, so a project file can add words
 * but can never silently drop the private words in the global file.
 */
export function mergeConfig(layers: readonly Partial<Config>[]): Config {
  const out: Config = { ...EMPTY_CONFIG, deny: [], warn: [], allowPaths: [], disabledKinds: [] }
  for (const l of layers) {
    if (l.deny) out.deny = [...new Set([...out.deny, ...l.deny])]
    if (l.warn) out.warn = [...new Set([...out.warn, ...l.warn])]
    if (l.publicPaths) out.publicPaths = [...l.publicPaths]
    if (l.allowPaths) out.allowPaths = [...l.allowPaths]
    if (l.disabledKinds) out.disabledKinds = [...l.disabledKinds]
  }
  return out
}

// ---- Paths ------------------------------------------------------------------

export type PathCtx = { cwd: string; home: string }

const GLOB_CHARS = /[*?]/

function escapeRe(s: string): string {
  return s.replace(/[.+^${}()|[\]\\*?]/g, '\\$&')
}

function globBody(glob: string): string {
  let re = ''
  for (let i = 0; i < glob.length; i += 1) {
    const c = glob[i]
    if (c === '*' && glob[i + 1] === '*') {
      if (glob[i + 2] === '/') {
        re += '(?:.*/)?'
        i += 2
      } else {
        re += '.*'
        i += 1
      }
    } else if (c === '*') {
      re += '[^/]*'
    } else if (c === '?') {
      re += '[^/]'
    } else {
      re += escapeRe(c)
    }
  }
  return re
}

function normalize(p: string): string {
  return p.replace(/\\/g, '/').replace(/\/+/g, '/')
}

/** The absolute and cwd-relative forms of a path. */
export function pathForms(path: string, ctx: PathCtx): { abs: string; rel: string } {
  let p = normalize(String(path ?? ''))
  const home = normalize(ctx.home || '')
  if (home && (p === '~' || p.startsWith('~/'))) p = home + p.slice(1)
  const cwd = normalize(ctx.cwd || '').replace(/\/$/, '')
  const abs = p.startsWith('/') ? p : cwd ? cwd + '/' + p.replace(/^\.\//, '') : p
  const rel = cwd && abs.startsWith(cwd + '/') ? abs.slice(cwd.length + 1) : abs
  return { abs, rel }
}

/**
 * Whether one config entry matches a path. Kept simple:
 * - an entry with `*` or `?` is a glob (`**` crosses folders). Without a `/` it
 *   is tested against the file name; otherwise against the path relative to
 *   the working directory, the absolute path, or any trailing part of it.
 * - any other entry matches, case-insensitively, wherever a path segment
 *   starts with it: `README` matches `docs/README.md`, `public/` matches
 *   `site/public/index.html`, `.env` matches `.env` and `.env.local`.
 * A leading `~/` stands for the home directory.
 */
export function pathMatches(entry: string, path: string, ctx: PathCtx): boolean {
  if (!entry || !path) return false
  const { abs, rel } = pathForms(path, ctx)
  let pat = normalize(entry)
  const home = normalize(ctx.home || '')
  if (home && (pat === '~' || pat.startsWith('~/'))) pat = home + pat.slice(1)
  if (GLOB_CHARS.test(pat)) {
    const body = globBody(pat)
    if (!pat.includes('/')) {
      const base = abs.slice(abs.lastIndexOf('/') + 1)
      return new RegExp('^' + body + '$').test(base)
    }
    if (pat.startsWith('/')) return new RegExp('^' + body + '$').test(abs)
    const anchored = new RegExp('^' + body + '$')
    const trailing = new RegExp('(?:^|/)' + body + '$')
    return anchored.test(rel) || trailing.test(abs)
  }
  const needle = pat.toLowerCase()
  if (needle.startsWith('/')) return abs.toLowerCase().startsWith(needle)
  const hay = '/' + abs.toLowerCase()
  return hay.includes('/' + needle) || ('/' + rel.toLowerCase()).includes('/' + needle)
}

export function anyPathMatches(entries: readonly string[], path: string, ctx: PathCtx): boolean {
  return entries.some(entry => pathMatches(entry, path, ctx))
}

/** Whether a shell command mentions a path that one of the entries matches. */
export function commandMentions(entries: readonly string[], command: string, ctx: PathCtx): boolean {
  const lower = command.toLowerCase()
  const tokens = command.split(/[\s'"`;|&<>()=]+/).filter(t => t !== '')
  return entries.some(entry => {
    if (!GLOB_CHARS.test(entry)) {
      const plain = entry.replace(/^~\//, '').toLowerCase()
      if (plain !== '' && lower.includes(plain)) return true
    }
    return tokens.some(t => pathMatches(entry, t, ctx))
  })
}

// ---- Scanning ---------------------------------------------------------------

export type Finding = {
  kind: string
  id: string
  action: Action
  masked: string
}

function wordRegex(phrase: string): RegExp | null {
  const words = phrase.trim().split(/\s+/).filter(w => w !== '').map(escapeRe)
  if (words.length === 0) return null
  return new RegExp('(?<![A-Za-z0-9_])' + words.join('\\s+') + '(?![A-Za-z0-9_])', 'i')
}

export type ScanOptions = {
  config: Config
  /** Whether the deny and warn word lists apply to this write. */
  wordsApply: boolean
}

/**
 * Every finding in `text`, blocks first. Overlapping matches of different
 * credential patterns are reported once (the earlier, stricter pattern wins).
 */
export function scan(text: string, opts: ScanOptions): Finding[] {
  if (typeof text !== 'string' || text === '') return []
  const disabled = new Set(opts.config.disabledKinds)
  const found: Finding[] = []
  const spans: [number, number][] = []
  for (const p of PATTERNS) {
    if (disabled.has(p.id)) continue
    const re = new RegExp(p.regex.source, p.regex.flags.includes('g') ? p.regex.flags : p.regex.flags + 'g')
    let m: RegExpExecArray | null
    while ((m = re.exec(text)) !== null) {
      if (m[0] === '') {
        re.lastIndex += 1
        continue
      }
      const start = m.index
      const end = start + m[0].length
      if (spans.some(([s, e]) => start < e && end > s)) continue
      const value = p.group ? m[p.group] ?? m[0] : m[0]
      if (p.skipPlaceholders && isPlaceholder(value)) continue
      spans.push([start, end])
      found.push({ kind: p.kind, id: p.id, action: p.action, masked: mask(value) })
    }
  }
  if (opts.wordsApply) {
    for (const [list, action, kind] of [
      [opts.config.deny, 'block', 'deny-listed word'],
      [opts.config.warn, 'warn', 'warn-listed word'],
    ] as const) {
      for (const phrase of list) {
        const re = wordRegex(phrase)
        const m = re ? re.exec(text) : null
        if (m) found.push({ kind, id: action === 'block' ? 'deny-word' : 'warn-word', action, masked: mask(m[0]) })
      }
    }
  }
  return [...found.filter(f => f.action === 'block'), ...found.filter(f => f.action === 'warn')]
}

// ---- What a tool call writes ------------------------------------------------

export type Target = {
  /** The file written, or null for a Bash command. */
  path: string | null
  /** Where, as shown in messages: the file path or 'Bash command'. */
  where: string
  /** Only the new text being written. */
  texts: string[]
}

function str(v: unknown): string | null {
  return typeof v === 'string' ? v : null
}

/** The new text a guarded tool call would write, or null for any other call. */
export function targetOf(e: Record<string, unknown>): Target | null {
  const tool = str(e.tool)
  if (tool === 'Bash') {
    const command = str(e.command)
    return { path: null, where: 'Bash command', texts: command ? [command] : [] }
  }
  const path = str(e.file_path) ?? str(e.notebook_path)
  const where = path ?? '(unknown file)'
  if (tool === 'Write') {
    const content = str(e.content)
    return { path, where, texts: content ? [content] : [] }
  }
  if (tool === 'Edit') {
    const added = str(e.new_string)
    return { path, where, texts: added ? [added] : [] }
  }
  if (tool === 'MultiEdit') {
    const edits = Array.isArray(e.edits) ? e.edits : []
    const texts = edits
      .map(x => (x !== null && typeof x === 'object' ? str((x as Record<string, unknown>).new_string) : null))
      .filter((x): x is string => x !== null && x !== '')
    return { path, where, texts }
  }
  if (tool === 'NotebookEdit') {
    const source = str(e.new_source)
    return { path, where, texts: source ? [source] : [] }
  }
  return null
}

export type Verdict = { findings: Finding[]; exempt: boolean }

/** Applies allowPaths and publicPaths, then scans each new text. */
export function judge(target: Target, config: Config, ctx: PathCtx): Verdict {
  if (target.path !== null && anyPathMatches(config.allowPaths, target.path, ctx)) {
    return { findings: [], exempt: true }
  }
  const pub = config.publicPaths
  const wordsApply =
    pub === null
      ? true
      : target.path !== null
        ? anyPathMatches(pub, target.path, ctx)
        : target.texts.some(t => commandMentions(pub, t, ctx))
  const findings = target.texts.flatMap(t => scan(t, { config, wordsApply }))
  return {
    findings: [...findings.filter(f => f.action === 'block'), ...findings.filter(f => f.action === 'warn')],
    exempt: false,
  }
}

export function blockMessage(f: Finding, where: string): string {
  return (
    `secret-guard: ${f.kind} detected in ${where} (${f.masked}). Secrets must not be written here. ` +
    `If this is intentional, add the path to allowPaths in .claude/secret-guard.json or run /secret-guard off for this session.`
  )
}

export function askQuestion(f: Finding, where: string, more: number): string {
  const extra = more > 0 ? ` and ${more} more` : ''
  return `secret-guard: possible ${f.kind} in ${where} (${f.masked})${extra}. Allow?`
}

/**
 * The band's parts, drawn as kit.line('secret-guard', chips, right): `secret-guard  ● 2 blocked  ● 1 allowed`
 * while on (blocked in danger and allowed in ok once nonzero, else quiet), or `secret-guard  ● off for this
 * session      /secret-guard on to resume` when off, which is urgent: the right side in the default text color.
 */
export type BandParts = { chips: { text: string; tone: 'danger' | 'ok' | 'muted' }[]; right: string; urgent: boolean }

export function bandParts(isOn: boolean, blocked: number, allowed: number): BandParts {
  if (!isOn) return { chips: [{ text: 'off for this session', tone: 'danger' }], right: '/secret-guard on to resume', urgent: true }
  return {
    chips: [
      { text: `${blocked} blocked`, tone: blocked > 0 ? 'danger' : 'muted' },
      { text: `${allowed} allowed`, tone: allowed > 0 ? 'ok' : 'muted' },
    ],
    right: '',
    urgent: false,
  }
}

