  typeBadge(fileName: string): unknown
  /** kit v3: a rounded bar (Svg surfaces; `width` in CSS pixels, absent: the slot's width) or bar(). */
  progress(ratio: number, opts?: { width?: number; tone?: Tone }): unknown
